-- Beta emails with a versioned logo URL (icon.png?v=…), so mail clients stop showing the old logo.
-- Generated by supabase/templates/build.mjs (same as beta/beta_templates.sql).
insert into private.email_templates (key, subject, html) values ('beta_confirm', $tpl$Konfirmasi email kamu untuk beta ScriptGo$tpl$, $tpl$<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<link href="https://fonts.googleapis.com/css2?family=Urbanist:wght@500;700;800&display=swap" rel="stylesheet">
<title>Konfirmasi email kamu</title>
</head>
<body style="margin:0;padding:0;background:#EEF2F6;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#EEF2F6;">Satu klik lagi, lalu kamu masuk daftar beta.</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F6;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <tr><td align="center" style="padding:32px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;">
      <tr><td style="padding:0 8px 20px;">
        <table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="vertical-align:middle;"><img src="https://scriptgo.id/icon.png?v=a87be887" width="36" height="36" alt="" style="display:block;border:0;"></td>
          <td style="vertical-align:middle;padding-left:10px;font-size:20px;font-weight:800;letter-spacing:-0.3px;color:#0E1116;">ScriptGo</td>
        </tr></table>
      </td></tr>
      <tr><td style="background:#FFFFFF;border-radius:28px;padding:0;overflow:hidden;">
        <div style="padding:32px 28px;">
        <h1 style="margin:0 0 12px;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-0.5px;color:#0E1116;">Konfirmasi email kamu</h1>
        <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;">Hai! Kamu baru saja mendaftar beta ScriptGo dengan email <strong style="color:#0E1116;font-weight:700;">{{email}}</strong>.</p><p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;">Klik tombol di bawah untuk memastikan email ini benar milikmu. Undangan beta hanya kami kirim ke email yang sudah dikonfirmasi.</p>
<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 20px;">
  <tr><td style="background:#0E1116;border-radius:999px;">
    <a href="{{link}}" style="display:inline-block;padding:15px 28px;font-size:16px;font-weight:700;color:#FFFFFF;text-decoration:none;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">Konfirmasi email</a>
  </td></tr>
</table><p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;font-size:14px;">Tombol tidak bisa diketuk? Buka link ini: <a href="{{link}}" style="color:#0369A1;font-weight:700;word-break:break-all;">{{link}}</a></p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 0;">
  <tr><td style="background:#F5F7FA;border-radius:16px;padding:14px 16px;font-size:14px;line-height:1.55;color:#5B6675;">Link berlaku 24 jam dan hanya bisa dipakai sekali. Tidak merasa mendaftar? Abaikan email ini.</td></tr>
</table>
        </div>
      </td></tr>
      <tr><td style="padding:20px 8px 0;font-size:13px;line-height:1.6;color:#5B6675;">
        Email otomatis dari ScriptGo untuk {{email}}. Kamu menerima email ini karena mendaftar beta di scriptgo.id.<br>
        <a href="https://scriptgo.id" style="color:#0369A1;font-weight:600;text-decoration:none;">scriptgo.id</a> ·
        <a href="https://scriptgo.id/privacy.html" style="color:#5B6675;text-decoration:underline;">Kebijakan privasi</a>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>
$tpl$)
on conflict (key) do update set subject = excluded.subject, html = excluded.html, updated_at = now();

insert into private.email_templates (key, subject, html) values ('beta_invite', $tpl$Kamu diterima di beta ScriptGo$tpl$, $tpl$<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<link href="https://fonts.googleapis.com/css2?family=Urbanist:wght@500;700;800&display=swap" rel="stylesheet">
<title>Selamat datang di beta ScriptGo</title>
</head>
<body style="margin:0;padding:0;background:#EEF2F6;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#EEF2F6;">Gabung lewat Google Play dan pasang ScriptGo di HP Android kamu.</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F6;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <tr><td align="center" style="padding:32px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;">
      <tr><td style="padding:0 8px 20px;">
        <table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="vertical-align:middle;"><img src="https://scriptgo.id/icon.png?v=a87be887" width="36" height="36" alt="" style="display:block;border:0;"></td>
          <td style="vertical-align:middle;padding-left:10px;font-size:20px;font-weight:800;letter-spacing:-0.3px;color:#0E1116;">ScriptGo</td>
        </tr></table>
      </td></tr>
      <tr><td style="background:#FFFFFF;border-radius:28px;padding:0;overflow:hidden;">
        <div style="padding:32px 28px;">
        <h1 style="margin:0 0 12px;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-0.5px;color:#0E1116;">Selamat datang di beta ScriptGo</h1>
        <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;">Halo <strong style="color:#0E1116;font-weight:700;">{{name}}</strong>, kamu termasuk pengguna pertama ScriptGo. Terima kasih sudah mau mencoba dan memberi masukan.</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 20px;">
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">1</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Buka email ini di <strong style="color:#0E1116;font-weight:700;">HP Android</strong>. Pastikan Play Store di HP itu masuk dengan akun Google <strong style="color:#0E1116;font-weight:700;">{{email}}</strong>.</td>
  </tr>
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">2</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Ketuk tombol di bawah, lalu ketuk <strong style="color:#0E1116;font-weight:700;">Jadi penguji</strong> (Become a tester).</td>
  </tr>
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">3</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Ketuk <strong style="color:#0E1116;font-weight:700;">Download di Google Play</strong>, pasang, lalu buka ScriptGo dan ikuti langkahnya.</td>
  </tr>
</table>
<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 20px;">
  <tr><td style="background:#0E1116;border-radius:999px;">
    <a href="https://play.google.com/apps/testing/id.scriptgo.keyboard" style="display:inline-block;padding:15px 28px;font-size:16px;font-weight:700;color:#FFFFFF;text-decoration:none;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">Gabung beta di Google Play</a>
  </td></tr>
</table><p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;font-size:15px;">Sudah jadi penguji? Pasang langsung dari <a href="https://play.google.com/store/apps/details?id=id.scriptgo.keyboard" style="color:#0369A1;font-weight:700;">halaman ScriptGo di Play Store</a>. Update beta datang otomatis lewat Play Store.</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 0;">
  <tr><td style="background:#F5F7FA;border-radius:16px;padding:14px 16px;font-size:14px;line-height:1.55;color:#5B6675;">Harga pendiri 50% tetap berlaku untuk email ini. Ada masukan atau kendala? Cukup balas email ini, kami baca semuanya. Tolong tetap pasang ScriptGo selama minimal 14 hari: itu syarat Google sebelum ScriptGo bisa rilis untuk umum.</td></tr>
</table>
        </div>
      </td></tr>
      <tr><td style="padding:20px 8px 0;font-size:13px;line-height:1.6;color:#5B6675;">
        Email otomatis dari ScriptGo untuk {{email}}. Kamu menerima email ini karena mendaftar beta di scriptgo.id.<br>
        <a href="https://scriptgo.id" style="color:#0369A1;font-weight:600;text-decoration:none;">scriptgo.id</a> ·
        <a href="https://scriptgo.id/privacy.html" style="color:#5B6675;text-decoration:underline;">Kebijakan privasi</a>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>
$tpl$)
on conflict (key) do update set subject = excluded.subject, html = excluded.html, updated_at = now();

insert into private.email_templates (key, subject, html) values ('beta_tips', $tpl$4 trik ScriptGo yang bikin balas chat makin cepat$tpl$, $tpl$<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<link href="https://fonts.googleapis.com/css2?family=Urbanist:wght@500;700;800&display=swap" rel="stylesheet">
<title>4 trik supaya ScriptGo makin terasa</title>
</head>
<body style="margin:0;padding:0;background:#EEF2F6;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#EEF2F6;">Isi nama pelanggan otomatis, tahan spasi, ganti karakter pemicu, dan pakai di laptop.</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F6;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <tr><td align="center" style="padding:32px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;">
      <tr><td style="padding:0 8px 20px;">
        <table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="vertical-align:middle;"><img src="https://scriptgo.id/icon.png?v=a87be887" width="36" height="36" alt="" style="display:block;border:0;"></td>
          <td style="vertical-align:middle;padding-left:10px;font-size:20px;font-weight:800;letter-spacing:-0.3px;color:#0E1116;">ScriptGo</td>
        </tr></table>
      </td></tr>
      <tr><td style="background:#FFFFFF;border-radius:28px;padding:0;overflow:hidden;">
        <div style="padding:32px 28px;">
        <h1 style="margin:0 0 12px;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-0.5px;color:#0E1116;">4 trik supaya ScriptGo makin terasa</h1>
        <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;">Halo <strong style="color:#0E1116;font-weight:700;">{{name}}</strong>, sudah 3 hari kamu pakai ScriptGo. Ini 4 trik yang paling sering bikin pengguna bilang "kok baru tahu".</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;">
  <tr><td style="background:#EEF2F6;border-radius:18px;padding:14px 16px;">
    <div style="font-size:16px;font-weight:800;color:#0E1116;margin-bottom:4px;">1. Nama pelanggan terisi sendiri</div>
    <div style="font-size:15px;line-height:1.55;color:#5B6675;">Tulis <span style="background:#E0F2FE;color:#0369A1;font-weight:700;border-radius:6px;padding:1px 6px;">{nama}</span> di template, misalnya <span style="background:#E0F2FE;color:#0369A1;font-weight:700;border-radius:6px;padding:1px 6px;">Halo Kak {nama}</span>. Saat dipakai, ScriptGo menanyakan "Untuk siapa?" dan mengisi nama, kota, atau data lain dari kontak.</div>
  </td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;">
  <tr><td style="background:#EEF2F6;border-radius:18px;padding:14px 16px;">
    <div style="font-size:16px;font-weight:800;color:#0E1116;margin-bottom:4px;">2. Tahan spasi untuk daftar template</div>
    <div style="font-size:15px;line-height:1.55;color:#5B6675;">Lupa nama shortcut? Tahan tombol spasi sekitar 1 detik: tombol keyboard berubah jadi daftar template, tinggal ketuk. Lama tahannya bisa diatur di pengaturan keyboard.</div>
  </td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;">
  <tr><td style="background:#EEF2F6;border-radius:18px;padding:14px 16px;">
    <div style="font-size:16px;font-weight:800;color:#0E1116;margin-bottom:4px;">3. Ganti karakter pemicu kalau bentrok</div>
    <div style="font-size:15px;line-height:1.55;color:#5B6675;">Pakai WhatsApp Business? Tanda <span style="background:#E0F2FE;color:#0369A1;font-weight:700;border-radius:6px;padding:1px 6px;">/</span> juga dipakai balas cepat WhatsApp. Di tab Template, ketuk ikon pengaturan dan ganti dengan <span style="background:#E0F2FE;color:#0369A1;font-weight:700;border-radius:6px;padding:1px 6px;">;</span> atau <span style="background:#E0F2FE;color:#0369A1;font-weight:700;border-radius:6px;padding:1px 6px;">\</span>.</div>
  </td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 12px;">
  <tr><td style="background:#EEF2F6;border-radius:18px;padding:14px 16px;">
    <div style="font-size:16px;font-weight:800;color:#0E1116;margin-bottom:4px;">4. Template yang sama di laptop</div>
    <div style="font-size:15px;line-height:1.55;color:#5B6675;">Masuk ke akun di tab Akun, lalu pasang Chrome extension ScriptGo. Template dan kontak ikut, bisa dipakai di WhatsApp Web dan kolom chat lain di browser.</div>
  </td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 0;">
  <tr><td style="background:#F5F7FA;border-radius:16px;padding:14px 16px;font-size:14px;line-height:1.55;color:#5B6675;">Ada yang bikin bingung? Balas email ini, kami bantu. Tidak mau menerima email beta lagi? Balas dengan kata <strong style="color:#0E1116;font-weight:700;">STOP</strong>.</td></tr>
</table>
        </div>
      </td></tr>
      <tr><td style="padding:20px 8px 0;font-size:13px;line-height:1.6;color:#5B6675;">
        Email otomatis dari ScriptGo untuk {{email}}. Kamu menerima email ini karena mendaftar beta di scriptgo.id.<br>
        <a href="https://scriptgo.id" style="color:#0369A1;font-weight:600;text-decoration:none;">scriptgo.id</a> ·
        <a href="https://scriptgo.id/privacy.html" style="color:#5B6675;text-decoration:underline;">Kebijakan privasi</a>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>
$tpl$)
on conflict (key) do update set subject = excluded.subject, html = excluded.html, updated_at = now();

insert into private.email_templates (key, subject, html) values ('beta_feedback', $tpl${{name}}, 3 pertanyaan singkat soal ScriptGo$tpl$, $tpl$<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<link href="https://fonts.googleapis.com/css2?family=Urbanist:wght@500;700;800&display=swap" rel="stylesheet">
<title>Boleh minta 2 menit?</title>
</head>
<body style="margin:0;padding:0;background:#EEF2F6;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#EEF2F6;">Balas email ini dengan jawabanmu. Masukanmu menentukan fitur berikutnya.</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F6;font-family:Urbanist, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <tr><td align="center" style="padding:32px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;">
      <tr><td style="padding:0 8px 20px;">
        <table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="vertical-align:middle;"><img src="https://scriptgo.id/icon.png?v=a87be887" width="36" height="36" alt="" style="display:block;border:0;"></td>
          <td style="vertical-align:middle;padding-left:10px;font-size:20px;font-weight:800;letter-spacing:-0.3px;color:#0E1116;">ScriptGo</td>
        </tr></table>
      </td></tr>
      <tr><td style="background:#FFFFFF;border-radius:28px;padding:0;overflow:hidden;">
        <div style="padding:32px 28px;">
        <h1 style="margin:0 0 12px;font-size:26px;line-height:1.2;font-weight:800;letter-spacing:-0.5px;color:#0E1116;">Boleh minta 2 menit?</h1>
        <p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#5B6675;">Halo <strong style="color:#0E1116;font-weight:700;">{{name}}</strong>, sudah 10 hari kamu ikut beta ScriptGo. Kami ingin tahu apa yang sudah membantu dan apa yang masih mengganggu. Cukup <strong style="color:#0E1116;font-weight:700;">balas email ini</strong>, jawab singkat saja:</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 20px;">
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">1</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Template apa yang paling sering kamu pakai, dan kira-kira berapa kali sehari?</td>
  </tr>
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">2</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Apa yang paling bikin repot, atau hampir bikin kamu berhenti pakai ScriptGo?</td>
  </tr>
  <tr>
    <td style="width:34px;vertical-align:top;padding:2px 0 12px;"><div style="width:26px;height:26px;border-radius:13px;background:#E0F2FE;color:#0369A1;font-size:14px;font-weight:800;line-height:26px;text-align:center;">3</div></td>
    <td style="vertical-align:top;padding:4px 0 12px;font-size:16px;line-height:1.5;color:#5B6675;">Kalau besok ScriptGo tidak bisa dipakai lagi, seberapa kecewa kamu? <strong style="color:#0E1116;font-weight:700;">Sangat kecewa</strong>, <strong style="color:#0E1116;font-weight:700;">agak kecewa</strong>, atau <strong style="color:#0E1116;font-weight:700;">biasa saja</strong>?</td>
  </tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 0;">
  <tr><td style="background:#FDECEC;border-radius:16px;padding:14px 16px;font-size:14px;line-height:1.55;color:#0E1116;"><strong style="color:#0E1116;font-weight:700;">Tolong jangan copot ScriptGo dulu.</strong> Google mewajibkan penguji tetap memasang app selama 14 hari sebelum ScriptGo boleh rilis untuk umum. Tinggal beberapa hari lagi. Terima kasih banyak!</td></tr>
</table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:8px 0 0;">
  <tr><td style="background:#F5F7FA;border-radius:16px;padding:14px 16px;font-size:14px;line-height:1.55;color:#5B6675;">Harga pendiri 50% tetap berlaku untuk email ini. Tidak mau menerima email beta lagi? Balas dengan kata <strong style="color:#0E1116;font-weight:700;">STOP</strong>.</td></tr>
</table>
        </div>
      </td></tr>
      <tr><td style="padding:20px 8px 0;font-size:13px;line-height:1.6;color:#5B6675;">
        Email otomatis dari ScriptGo untuk {{email}}. Kamu menerima email ini karena mendaftar beta di scriptgo.id.<br>
        <a href="https://scriptgo.id" style="color:#0369A1;font-weight:600;text-decoration:none;">scriptgo.id</a> ·
        <a href="https://scriptgo.id/privacy.html" style="color:#5B6675;text-decoration:underline;">Kebijakan privasi</a>
      </td></tr>
    </table>
  </td></tr>
</table>
</body>
</html>
$tpl$)
on conflict (key) do update set subject = excluded.subject, html = excluded.html, updated_at = now();
